"""FIFO representation, lifetime, typed/plain stream operations and locking."""
def register(topic, q, detail):
    def lesson(title, path, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', path, symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('FIFO 저장 구조·누적 카운터와 원형 위치', 'include/linux/kfifo.h', '__kfifo',
        '먼저 들어온 자료를 먼저 꺼내는 큐의 상태를 어떤 숫자와 포인터로 저장하는지 배웁니다.',
        '__kfifo는 입력 누적 수 in, 출력 누적 수 out, 용량-1인 mask, 원소 바이트 크기 esize와 저장 공간 data를 가집니다. 사용 원소 수는 부호 없는 in-out이고 실제 배열 위치는 누적 수 & mask입니다. 용량은 2의 거듭제곱이라 AND가 배열 끝을 넘는 위치를 처음으로 감습니다. 카운터 자체를 매번 용량 범위로 줄이는 방식이 아닙니다.',
        '용량·원소 개수·바이트 수를 구분합니다. 같은 인덱스가 다시 나오더라도 in-out으로 비어 있음과 가득 참을 구분할 수 있습니다. 사용량이 용량을 넘지 않도록 각 입력·출력의 실제 처리 개수로 카운터를 갱신합니다.',
        '용량 8에서 in=11,out=6의 사용량과 실제 두 위치를 계산하세요.',
        [('용량 8, in=11,out=6의 사용량은?', '5개다', '실제 위치 3과 6이므로 항상 비어 있다', '누적 차이 11-6=5입니다. 배열 위치는 각각 3과 6이지만 위치의 대소만으로 사용량을 계산하지 않습니다.'),
         ('용량 8에서 누적 위치 11의 배열 인덱스는?', '11&7=3이다', '반드시 배열 밖 11이다', 'mask는 용량-1인 7입니다. 2의 거듭제곱 용량에서는 낮은 비트만 남기는 AND로 위치를 감습니다.')],
        [('카운터 감김', 'unsigned int의 감김은 정해진 폭의 나머지 산술입니다. 사용량이 유효 범위 안에 있고 용량이 같은 폭의 감김과 맞는 2의 거듭제곱이라는 조건에서 차이와 위치가 유지됩니다.'),
         ('동시성 기본 조건', '헤더는 독자 한 명·writer 한 명이며 reset이 없는 사용에서는 추가 잠금이 필요 없다고 설명합니다. 여러 writer 또는 reader, reset·수명 변경은 별도의 직렬화 조건이 필요합니다.')])

    lesson('FIFO 타입 매크로·내장 배열과 외부 저장 공간', 'include/linux/kfifo.h', '__STRUCT_KFIFO_COMMON',
        '범용 큐가 원소 타입과 레코드 길이 폭을 컴파일 시점에 연결하는 방법을 배웁니다.',
        '공통 union은 실제 __kfifo와 타입을 알려주는 type·const_type·ptr·ptr_const·rectype 멤버를 겹칩니다. 매크로는 typeof와 sizeof로 원소 형식과 레코드 폭을 얻습니다. STRUCT_KFIFO는 내장 buf 배열을 가지며 크기가 2 미만이거나 2의 거듭제곱이 아니면 음수 배열 크기로 선언을 거절합니다. PTR 형태는 길이 0 배열로 외부 저장 형태를 표현합니다.',
        'DECLARE_KFIFO는 고정 용량, DECLARE_KFIFO_PTR는 별도 할당·외부 버퍼용 객체 선언에 사용합니다. struct kfifo는 unsigned char 호환형이고 REC_1·REC_2는 길이 헤더 폭 1·2의 레코드 큐입니다. 데이터 버퍼와 타입 표시용 포인터를 같은 실제 저장 자료라고 읽지 않습니다.',
        '두 구조 매크로, 음수 배열 조건과 __is_kfifo_ptr의 sizeof 비교를 읽으세요.',
        [('STRUCT_KFIFO의 크기 6 선언은 왜 거절되는가?', '2의 거듭제곱이 아니기 때문이다', '모든 큐는 크기 6만 허용하기 때문이다', '6&5는 0이 아닙니다. 원형 AND 위치 계산에 맞는 크기를 강제하며 조건 위반은 음수 배열 크기로 드러납니다.'),
         ('rectype의 sizeof가 나타내는 것은?', '레코드 길이 헤더의 바이트 폭이다', '항상 데이터 포인터의 주소 폭이다', 'char 배열을 가리키는 타입으로 recsize를 표현합니다. 일반 큐는 0, 레코드 형태는 1 또는 2바이트 헤더 폭을 사용합니다.')],
        [('GNU C 확장', '길이 0 배열, typeof와 statement expression은 여기의 GNU C 매크로 구현에 사용됩니다. 일반 ISO C의 모든 컴파일러가 같은 형태를 허용한다고 설명하지 않습니다.'),
         ('호환형과 레코드형', 'kfifo_rec_ptr_1·2와 STRUCT_KFIFO_REC_1·2의 원소는 바이트입니다. 임의의 esize와 recsize를 독립적으로 섞는 일반 구조라고 사용하지 않습니다.')])

    lesson('FIFO 초기화·선언 뒤 INIT와 DEFINE', 'include/linux/kfifo.h', 'INIT_KFIFO',
        '큐 객체를 선언하는 일과 실제 저장 공간을 연결하는 일을 구분해 배웁니다.',
        'INIT_KFIFO는 in과 out을 0으로 만들고 원소 크기를 sizeof(buf 원소)로 설정합니다. 내장 배열이면 mask=ARRAY_SIZE(buf)-1, data=buf를 저장합니다. 외부 저장 형태면 mask=0,data=NULL로 만들어 아직 저장 공간이 없는 상태입니다. DEFINE_KFIFO는 선언과 같은 초기값 구성을 함께 수행합니다.',
        '내장 객체는 INIT_KFIFO 또는 DEFINE_KFIFO로 준비합니다. PTR 객체는 INIT만으로 사용 가능한 공간이 생기지 않으므로 kfifo_alloc 또는 kfifo_init을 이어서 호출합니다. 초기화 중 다른 접근이 없도록 수명과 진입 시점을 제어합니다.',
        '__is_kfifo_ptr의 양쪽 mask·data 선택과 DEFINE 초기화 필드를 읽으세요.',
        [('PTR 객체에 INIT_KFIFO만 호출하면?', '카운터는 초기화되지만 저장 공간은 아직 없다', '자동으로 용량 1024 버퍼를 할당한다', '외부 저장 형태는 mask=0,data=NULL입니다. INIT에는 할당 호출이 없고 이후 alloc 또는 외부 버퍼 연결이 필요합니다.'),
         ('내장 용량 16 객체의 INIT mask는?', '15다', '16다', '배열 위치를 AND로 감기 위해 용량에서 1을 뺀 mask를 저장합니다. in과 out은 모두 0에서 시작합니다.')],
        [('정적·지역 정의', 'DEFINE_KFIFO는 전역과 지역 정의에서 사용할 수 있는 초기화 매크로입니다. 포함 배열이 초기화에서 따로 나열되지 않아도 C의 나머지 필드 초기화 규칙이 적용됩니다.'),
         ('포팅 안내', '헤더의 예전 API 포팅 주석은 큐 객체 자체를 제자리 구조로 바꾸고 주소를 넘기며, spinlock을 초기화 함수가 아니라 spinlocked 입출력의 마지막 인자로 옮기라고 설명합니다. 오래된 함수 이름을 현재 호출과 섞지 않습니다.')])

    lesson('FIFO 동적 할당·원소 용량 올림과 해제', 'lib/kfifo.c', '__kfifo_alloc',
        '요청한 원소 용량을 2의 거듭제곱으로 올리고 오류와 해제를 처리하는 방법을 배웁니다.',
        '__kfifo_alloc은 원소 수를 roundup_pow_of_two로 올리고 in·out을 초기화합니다. 용량 2 미만이면 -EINVAL, kmalloc_array(esize,size)가 실패하면 -ENOMEM입니다. 성공하면 mask=size-1입니다. __kfifo_free는 저장 공간을 해제하고 카운터·크기·포인터·mask를 모두 초기화합니다. 공개 alloc/free 매크로는 PTR 형태에만 이 동작을 적용합니다.',
        '예를 들어 17개 원소를 요청하면 32개 공간을 준비합니다. esize는 양수이며 타입과 맞아야 합니다. roundup의 0 입력은 정의되지 않은 조건이므로 뒤의 size<2 검사만 믿고 제로 용량을 전달하지 않습니다. 할당된 외부 저장과 사용자가 제공한 버퍼의 소유권을 구분합니다.',
        '올림 위치, 두 오류 분기, 해제의 필드 초기화를 읽으세요.',
        [('17개 원소 요청의 정상 할당 용량은?', '32개다', '16개다', '동적 할당은 요청을 수용하도록 다음 2의 거듭제곱으로 올립니다. 외부 버퍼를 아래로 줄이는 init과 방향이 다릅니다.'),
         ('내장 배열 객체에 공개 kfifo_alloc을 호출하면?', '-EINVAL을 반환한다', '내장 배열을 자동으로 realloc한다', '매크로는 __is_kfifo_ptr를 검사합니다. 내장 버퍼 구조에 동적 저장을 할당하는 API가 아니므로 오류를 반환합니다.')],
        [('배열 할당 검사', 'kmalloc_array는 원소 크기와 개수를 분리해서 받아 곱 크기의 유효성을 처리하는 커널 할당 API입니다. FIFO 카운터와 원소 크기의 표현 가능 범위도 호출자가 지켜야 합니다.'),
         ('해제 책임', 'kfifo_free는 PTR 저장을 해제합니다. kfifo_init에 빌린 버퍼를 연결했다고 그 버퍼를 이 함수로 무조건 해제해도 되는 계약은 아닙니다. 원래 할당·소유권 규약을 따릅니다.')])

    lesson('FIFO 외부 버퍼·바이트 크기를 원소 용량으로 내림', 'lib/kfifo.c', '__kfifo_init',
        '이미 준비한 버퍼를 넘치지 않게 원소 개수와 2의 거듭제곱 용량으로 바꾸는 방법을 배웁니다.',
        '__kfifo_init의 size는 버퍼 바이트 수입니다. 먼저 esize로 나누어 원소 수를 구하고, 그 수가 2의 거듭제곱이 아니면 rounddown_pow_of_two로 내립니다. 카운터와 data·esize를 설정하고 용량 2 미만이면 -EINVAL, 아니면 mask를 저장합니다. 실제 구현은 올림이라는 헤더 주석 문장과 달리 내림입니다.',
        '원소 크기 4바이트 버퍼 76바이트라면 19개에서 16개 용량을 사용합니다. esize=0이나 나눗셈 후 원소 수 0은 올바른 호출 조건으로 취급하지 않습니다. 저장 공간 수명은 큐 사용 기간보다 길어야 합니다.',
        'size/=esize와 rounddown 분기를 공개 주석과 대조하세요.',
        [('4바이트 원소와 76바이트 버퍼의 사용 용량은?', '16개 원소다', '32개 원소로 올려 버퍼 밖까지 쓴다', '76/4=19개이고 2의 거듭제곱으로 내리면 16개입니다. 동적 할당과 달리 기존 버퍼를 넘치게 늘릴 수 없습니다.'),
         ('바이트 size와 원소 개수를 같은 단위로 넘겨도 되는가?', '안 되며 init은 바이트 크기를 받는다', 'esize가 얼마든 항상 같다', '내부에서 size를 esize로 나눕니다. 개수를 바이트 크기로 착각해 넘기면 예상보다 작은 용량이 되거나 조건을 위반합니다.')],
        [('0의 경계', 'log2 header는 rounddown_pow_of_two(0)를 정의하지 않습니다. 작은 용량 오류 검사보다 먼저 계산하므로 실제 양수 원소 수 조건을 확인해야 합니다.'),
         ('기존 저장 소유권', 'init은 새 메모리를 할당하지 않고 전달된 포인터를 저장합니다. 버퍼의 해제 방법과 시점은 호출자가 가진 원래 소유권에 연결됩니다.')])

    lesson('FIFO 여유와 부분 입력·처리한 개수만 공개하기', 'lib/kfifo.c', '__kfifo_in',
        '공간이 부족할 때 전체 요청이 아니라 들어간 원소 수를 반환하는 큐 동작을 배웁니다.',
        'kfifo_unused는 용량-(in-out)입니다. __kfifo_in은 요청 len을 그 여유로 제한하고 실제 len만 복사한 뒤 in을 그만큼 늘려 반환합니다. __kfifo_out_peek는 len을 사용량으로 제한해 복사만 하고 out은 바꾸지 않습니다. __kfifo_out은 peek의 실제 결과만큼 out을 늘립니다. 일반 큐는 요청의 일부만 처리할 수 있습니다.',
        '반환한 원소 수로 남은 입력·출력을 처리합니다. 버퍼 용량과 요청 단위를 맞추고 성공을 단순 참·거짓으로 해석하지 않습니다. 레코드 입력의 전부 또는 0 계약과 일반 큐의 부분 처리 계약을 구분합니다.',
        '여유·사용량 제한과 반환값으로 카운터를 갱신하는 흐름을 읽으세요.',
        [('용량 8에 6개 사용 중일 때 5개를 일반 입력하면?', '최대 2개가 들어가고 2를 반환한다', '항상 5개를 써서 기존 자료를 덮어쓴다', '여유는 8-6=2입니다. 요청을 여유로 제한하고 실제 복사 수만 in에 더합니다.'),
         ('일반 out_peek는 어떤 상태를 유지하는가?', 'out 카운터를 유지해 자료를 제거하지 않는다', '항상 읽은 길이만큼 out을 증가한다', 'peek는 사용량 제한과 복사를 수행하지만 out 갱신은 없습니다. 실제 제거는 out wrapper가 반환 길이를 더해 수행합니다.')],
        [('공개 단위', 'kfifo_in·out·out_peek는 일반 타입 큐에서 원소 개수를 받습니다. u32 3개는 12바이트이지만 반환 3을 바이트 3으로 읽지 않습니다.'),
         ('기존 선언 연결', '헤더의 extern __kfifo_* 선언과 타입 분기 매크로를 실제 lib 구현에 연결합니다. 반환 검사 helper의 __must_check는 결과를 무시하지 않도록 컴파일러에 알리는 속성입니다.')])

    lesson('FIFO 복사·배열 끝을 넘는 두 조각과 공개 순서', 'lib/kfifo.c', 'kfifo_copy_in',
        '원형 저장 공간을 선형 입력·출력 버퍼와 연결하는 두 번의 복사를 배웁니다.',
        'off를 mask로 감고 원소 크기가 1이 아니면 off·용량·len을 모두 바이트로 바꿉니다. 첫 길이 l=min(len,size-off)는 현재 위치부터 배열 끝까지입니다. 나머지 len-l은 배열 처음에 복사합니다. 출력은 반대 방향으로 같은 두 조각을 복사합니다. 마지막 smp_wmb는 자료 복사 뒤 누적 카운터를 갱신하는 호출 흐름과 연결됩니다.',
        '원소 단위와 바이트 단위 전환을 한 번씩 정확히 수행합니다. 배열 끝에서 감기는 예를 추적하고 버퍼가 충분한지 확인합니다. 메모리 배리어만으로 여러 생산자의 예약 경쟁이나 노드 수명을 보호한다고 해석하지 않습니다.',
        '두 memcpy의 위치·길이와 호출 뒤 in·out 갱신을 읽으세요.',
        [('용량 8바이트, 위치 6에서 길이 5를 복사하면?', '끝쪽 2바이트와 처음 3바이트로 나눈다', '배열 밖으로 연속 5바이트를 쓴다', 'size-off=2라 첫 복사는 2입니다. 나머지 3은 배열 처음으로 이동해 원형 위치에 맞게 처리합니다.'),
         ('esize=4인 len=3은 복사 계산에서 몇 바이트인가?', '12바이트다', '3바이트다', 'len은 원소 수입니다. esize가 1이 아니면 복사 helper가 len·off·용량을 원소 크기로 곱해 바이트 단위로 변환합니다.')],
        [('입력 배리어', '입력은 자료를 쓴 뒤 in을 공개합니다. 출력은 자료를 외부로 복사한 뒤 out을 늘려 재사용을 허용합니다. 실제 커널 문맥의 배리어 계약과 순차 모의 시험을 구분합니다.'),
         ('복사 전제', '유효한 큐 사용량과 여유 제한 안의 길이로 호출합니다. 내부 helper가 임의 길이와 모든 겹치는 버퍼를 별도로 검사해 주지는 않습니다.')])

    lesson('FIFO 단일 원소·put·get·peek의 타입과 반환', 'include/linux/kfifo.h', 'kfifo_put',
        '원소 하나를 다루는 매크로와 타입 검사·레코드 분기를 배웁니다.',
        'put은 값을 타입에 맞는 임시 변수에 보관합니다. 일반 큐는 가득 차지 않았으면 배열 위치에 한 값을 쓰고 배리어 후 in을 늘립니다. get은 비어 있지 않으면 한 값을 읽고 배리어 후 out을 늘립니다. peek는 같은 값을 읽되 out을 바꾸지 않습니다. 레코드 형태는 해당 record helper로 분기합니다.',
        '일반 큐에서는 반환 1이 한 원소 처리, 0이 공간 없음·자료 없음입니다. 출력 값 포인터와 원소 타입을 맞춥니다. 레코드 타입은 바이트 payload와 길이 헤더를 다루는 별도 계약이므로 일반 단일 값 규칙만으로 설명하지 않습니다.',
        'typeof 임시 값과 ptr 타입, recsize 분기·카운터 갱신을 비교하세요.',
        [('일반 get이 빈 큐에서 0을 반환하면 출력 값은?', '유효하게 읽은 새 원소로 사용할 수 없다', '항상 원본이 숫자 0을 써 준다', '비어 있으면 값을 대입하는 본문이 실행되지 않습니다. 반환 0을 확인하고 기존 출력 변수의 내용을 새 자료라고 사용하지 않습니다.'),
         ('일반 peek가 반환 1이면 out도 늘어나는가?', '아니며 같은 자료를 다음 get으로 읽을 수 있다', '늘어나서 자료가 바로 사라진다', 'peek는 카운터를 갱신하지 않습니다. 값 관찰과 소비를 구분하는 매크로입니다.')],
        [('단일 평가', 'fifo와 val 식을 임시 변수에 저장하는 매크로 구조를 읽습니다. 타입 검사용 포인터와 실제 데이터 저장 포인터의 역할도 구분합니다.'),
         ('입출력 타입', '일반 큐의 type·const_type과 ptr·ptr_const는 값과 버퍼 표현을 연결합니다. record형은 void 포인터를 허용하는 바이트 전달 경로와 함께 읽어야 합니다.')])

    lesson('FIFO 선형 구간·한 번에 접근 가능한 원소 수', 'lib/kfifo.c', '__kfifo_out_linear',
        '복사하지 않고 배열 끝 전의 연속 자료 구간을 얻는 원리를 배웁니다.',
        '일반 큐는 off=out&mask를 tail에 저장합니다. 반환 길이는 요청 n, 사용량 in-out, 배열 끝까지 size-off의 최솟값입니다. 공개 linear_ptr는 그 tail에 esize를 곱해 data 포인터에 더합니다. 이 관찰만으로 자료가 소비되지는 않으며 실제 처리한 수를 별도 소비 흐름에 연결합니다.',
        '일반 큐의 tail은 원소 인덱스입니다. 배열 끝을 넘는 전체 사용량을 반환 길이로 착각하지 않습니다. record형의 별도 구현은 같은 경계 동작을 보장하지 않으므로 레코드 선형 수업의 원본 차이를 확인합니다.',
        'min3의 세 제한과 linear_ptr의 esize 곱을 읽으세요.',
        [('용량 8, out 위치 6, 사용 5개, 요청 5개이면 선형 길이는?', '2개다', '5개다', '자료는 5개지만 배열 끝까지 2개만 연속입니다. 감긴 나머지를 같은 포인터의 연속 메모리로 읽을 수 없습니다.'),
         ('u32 큐에서 tail=3의 포인터 바이트 오프셋은?', '12바이트다', '3바이트다', 'tail은 일반 큐의 원소 위치입니다. linear_ptr가 esize=4를 곱해 data+12에 연결합니다.')],
        [('소비 별도', 'linear는 조회 함수입니다. 처리 완료 길이에 맞는 skip 또는 소비 갱신을 호출자가 수행하며 실제 접근 기간에는 저장 내용이 재사용되지 않게 사용 규약을 지킵니다.'),
         ('빈 경계', '일반 __kfifo_out_linear는 사용량 0에서도 tail에 감긴 out 위치를 기록하고 길이 0을 반환합니다. record형의 빈 반환에서는 tail 갱신 여부가 다릅니다.')])

    lesson('FIFO 상태·여유와 reset·skip의 호출 조건', 'include/linux/kfifo.h', 'kfifo_skip_count',
        '상태 조회와 자료 건너뛰기·전체 초기화의 다른 의미를 배웁니다.',
        'initialized는 mask가 있는지 보고, size·esize·recsize·len·empty·full은 저장된 상태로 계산합니다. avail은 일반 큐의 빈 원소 수이며 record형은 길이 헤더 공간과 표현 가능한 최대 길이를 제외합니다. skip_count는 일반 큐에서 out에 count를 더하고 record형에서는 count와 무관하게 다음 record 하나를 건너뜁니다. reset은 두 카운터를 0으로, reset_out은 out=in으로 만듭니다.',
        '일반 skip의 count는 실제 사용량 이하여야 하며 함수가 자동으로 제한하지 않습니다. record skip과 peek_len은 유효한 다음 레코드가 있을 때 사용합니다. reset은 독점 접근이 필요하고 reset_out은 한 reader가 자기 문맥에서 실행하는 조건을 따릅니다.',
        '두 reset과 skip의 recsize 분기, avail의 헤더 차감을 읽으세요.',
        [('일반 큐에 사용 3개인데 skip_count(8)을 호출하면?', '유효한 사용량 조건을 위반한다', '항상 3으로 자동 제한된다', '일반 skip_count는 out에 count를 그대로 더합니다. 조회·복사 함수의 길이 제한과 달리 호출자가 범위를 지켜야 합니다.'),
         ('record 큐의 skip_count에서 count가 나타내는 소비 개수는?', '이 경로는 count와 무관하게 다음 record 하나를 건너뛴다', '언제나 count개의 record를 반복 삭제한다', 'recsize가 있으면 __kfifo_skip_r를 한 번 호출합니다. count를 record 수로 해석하면 실제 source 동작과 다릅니다.')],
        [('initialized 전제', '헤더 주석은 초기화 전 큐가 0이었다는 조건을 명시합니다. 임의 미초기화 mask를 읽어 valid 상태를 판정할 수 없습니다.'),
         ('반환 검사', '__kfifo_uint_must_check_helper와 int helper는 값을 그대로 반환하면서 __must_check 속성을 연결합니다. 이름이 입력 길이를 유효하게 제한하는 runtime 검사라는 뜻은 아닙니다.')])

    lesson('FIFO 잠금 wrapper·IRQ 저장과 같은 쪽 직렬화', 'include/linux/kfifo.h', 'kfifo_in_spinlocked',
        '여러 생산자·소비자가 있는 큐에서 필요한 쪽의 변경을 직렬화하는 wrapper를 배웁니다.',
        'spinlocked 입력·출력·empty 조회는 IRQ 상태를 저장한 spin_lock_irqsave로 연산을 감싸고 unlock_irqrestore로 복원합니다. noirqsave 형태는 spin_lock·unlock만 사용합니다. in_locked·out_locked는 기존 spinlocked 이름의 alias입니다. 한 reader와 여러 writer이면 writer 쪽 직렬화, 한 writer와 여러 reader이면 reader 쪽 직렬화가 필요합니다.',
        '같은 쪽 호출들이 동일한 올바른 락 규약을 사용해야 합니다. 조회 결과는 잠금 해제 뒤에도 영구 예약된 상태라는 뜻이 아닙니다. IRQ 재진입 가능성과 실행 문맥을 고려해 noirqsave를 선택하며 reset과 해제는 전체 접근 조건을 별도로 지킵니다.',
        '세 조회·입출력 wrapper의 flags 저장과 noirqsave 차이를 읽으세요.',
        [('noirqsave wrapper가 기본으로 하지 않는 것은?', 'IRQ 상태를 저장하고 비활성화·복원하는 처리다', '큐 연산을 실행하는 처리다', 'noirqsave는 spin_lock·unlock을 사용합니다. irqsave의 flags 보호와 같은 동작이라고 사용하면 실행 문맥 조건을 놓칩니다.'),
         ('empty를 잠금으로 확인한 뒤 락을 풀면 빈 상태가 예약되는가?', '아니며 이후 다른 흐름이 상태를 바꿀 수 있다', '조회가 모든 미래 입력을 막는다', '잠금은 조회 순간의 접근을 보호합니다. 해제 뒤 상태 변경을 막는 예약 기능이나 입출력 전체 트랜잭션을 제공하지 않습니다.')],
        [('독자·writer 분리', '한 reader와 한 writer가 각자의 카운터를 갱신하는 조건을 바탕으로 추가 잠금 규칙을 설명합니다. 여러 흐름이 같은 in 또는 out을 갱신하면 같은 쪽을 직렬화해야 합니다.'),
         ('시험 모의 락', '순차 fixture의 락 호출 모델은 lock/unlock와 IRQ 저장 경로가 연결되는지 확인합니다. 실제 커널 spinlock·IRQ·SMP 메모리 모델의 동작 검증으로 표시하지 않습니다.')])
